#pragma once

#include <QObject>
#include <array>
#include <memory>
#include <optional>
#include <vector>

#include "analyzer/plugins/analyzerplugin.h"
#include "analyzer/plugins/buffering_utils.h"
#include "analyzer/plugins/qmbeatmap.h"

class DetectionFunction;

namespace mixxx {

class AnalyzerQueenMaryBeats : public AnalyzerBeatsPlugin {
  public:
    static AnalyzerPluginInfo pluginInfo() {
        return AnalyzerPluginInfo(
                // Don't change this ID. It was auto generated by VAMP until
                // Mixxx 2.1 and we keep it for a compatible config.
                "qm-tempotracker:0",
                QObject::tr("Queen Mary University London"),
                QObject::tr("Queen Mary Tempo and Beat Tracker"),
                true);
    }

    AnalyzerQueenMaryBeats();
    ~AnalyzerQueenMaryBeats() override;

    AnalyzerPluginInfo info() const override {
        return pluginInfo();
    }

    bool initialize(mixxx::audio::SampleRate sampleRate) override;
    bool processSamples(const CSAMPLE* pIn, SINT iLen) override;
    bool finalize() override;

    bool supportsBeatTracking() const override {
        return true;
    }

    QVector<mixxx::audio::FramePos> getBeats() const override {
        return m_resultBeats;
    }

    std::optional<ConstantBeatGrid> getConstantBeatGrid() const override {
        return m_resultBeatMap.constantGrid;
    }

    QVector<mixxx::audio::FramePos> getBeatMap() const override {
        return m_resultBeatMap.beats;
    }

    void setBeatMapEnabled(bool enabled) override {
        m_beatMapEnabled = enabled;
    }

  private:
    std::unique_ptr<DetectionFunction> m_pDetectionFunction;
    DownmixAndOverlapHelper m_helper;
    mixxx::audio::SampleRate m_sampleRate;
    int m_windowSize;
    int m_stepSizeFrames;
    std::vector<double> m_detectionResults;
    // kQmOnsetBands spectrum magnitude sums per detection result, and the
    // first spectrum bin of each band, plus the end bin of the last band.
    std::vector<float> m_bandMagnitudes;
    std::array<int, kQmOnsetBands + 1> m_bandBins;
    QVector<mixxx::audio::FramePos> m_resultBeats;
    QmBeatMap m_resultBeatMap;
    bool m_beatMapEnabled = true;
};

} // namespace mixxx
